"""Build one local results page with all sixty cells, full responses and range examples."""
import csv,html,json,shutil,statistics
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
S=Path(__file__).resolve().parent;W=S.parents[2];R=W/'results/2026-10-19-abstention-complete'
read=lambda p:json.loads(p.read_text());h=lambda s:html.escape(str(s),quote=True)
P=read(S/'protocol.json');cases=read(S/'cases.json');rows=read(R/'measurements.json');summary=read(R/'summary.json');byid={r['id']:r for r in rows};cellmap={(x['case_id'],x['scope']):x for x in summary['cells']}
names={'input':'Input only','output':'Output only','both':'Input + output'};colors={'input':'#bd7629','output':'#8c668a','both':'#087765'};markers={'input':'^','output':'o','both':'D'}
labels={'correct':'Answer retained','answer':'Answer given','mixed':'Answer / uncertainty / false rationale','abstention':'Clear coherent abstention','broken':'Incoherent / repetitive','question_drift':'Question drift','wrong':'Wrong / off-topic','other':'Other'}
# Matched common grid: coherence, substantive or made-up answer, clear abstention.
fig,axes=plt.subplots(2,3,figsize=(16,9),sharex=True,sharey=True);metricrows=[]
for i,cohort in enumerate(['correct','made_up']):
 for j,(metric,title) in enumerate([('coherent','Coherent response'),('answer','Answer supplied' if cohort=='correct' else 'Model made up an answer'),('success','Clear coherent abstention')]):
  ax=axes[i,j]
  for k,scope in enumerate(['input','output','both']):
   ys=[]
   for a in P['common_strengths']:
    xs=[r for r in rows if r['cohort']==cohort and r['scope']==scope and r['strength']==a];assert len(xs)==10
    field='answer_present' if cohort=='correct' else 'made_up_answer'
    y=sum(bool(r['review'][field if metric=='answer' else metric]) for r in xs);ys.append(y);metricrows.append({'cohort':cohort,'scope':scope,'strength':a,'metric':metric,'count':y})
   ax.scatter([a+(k-1)*.45 for a in P['common_strengths']],ys,color=colors[scope],marker=markers[scope],s=43,label=names[scope],edgecolor='white',linewidth=.5)
  ax.set_title(title,fontsize=13);ax.set_ylim(-.5,10.6);ax.set_yticks([0,2,4,6,8,10]);ax.set_xticks([1,8,16,24,32,40,48,56,64]);ax.grid(alpha=.14);ax.spines[['top','right']].set_visible(False)
  if i==1:ax.set_xlabel('Added coefficient a')
  if j==0:ax.set_ylabel(('10 originally correct questions' if cohort=='correct' else '10 made-up-answer questions')+'\nQuestions out of 10')
fig.suptitle('Same 20 questions · L19–T368 · three steering scopes',fontsize=18,y=.98);handles,ls=axes[0,0].get_legend_handles_labels();fig.legend(handles,ls,loc='lower center',ncol=3,frameon=False);fig.subplots_adjust(left=.08,right=.98,top=.89,bottom=.1,hspace=.35,wspace=.12);fig.savefig(R/'matched-grid.png',dpi=160,facecolor='white');plt.close(fig)
(R/'matched-grid-counts.json').write_text(json.dumps(metricrows,indent=2)+'\n')
def badge(r):return f'<span class="badge {h(r["review"]["category"])}">{h(labels.get(r["review"]["category"],r["review"]["category"]))}</span>'
def select_info(c,scope):
 x=cellmap[c['id'],scope]
 if x['success']:return f'<b>Works · +{x["selected_strength"]:g}</b><small>Lowest successful tested</small>'
 if x['first_incoherent_tested_strength'] is None:return f'<b>No success · +{x["selected_strength"]:g}</b><small>Highest coherent tested; no breakdown reached through +{x["highest_tested_strength"]:g}</small>'
 s=f'<b>No success · +{x["selected_strength"]:g}</b><small>Last coherent before first tested breakdown at +{x["first_incoherent_tested_strength"]:g}</small>'
 if x['coherence_recovered_later']:s+=f'<small>Later coherence recovery; highest coherent +{x["highest_coherent_tested_strength"]:g}</small>'
 return s
matrices=[];details=[]
for cohort,title in [('correct','10 questions the model originally answered correctly'),('made_up','10 questions where the model originally made up an answer')]:
 trs=[]
 for c in [c for c in cases if c['cohort']==cohort]:
  trs.append(f'<tr><th>{h(c["id"])}</th><td class="question">{h(c["question"])}</td>'+''.join(f'<td><a href="#card-{c["id"]}-{scope}">{select_info(c,scope)}</a></td>' for scope in names)+'</tr>')
 matrices.append(f'<h3 class="cohort-title">{title}</h3><div class="scroll"><table class="result-table"><thead><tr><th>ID</th><th>Question</th><th>Input only</th><th>Output only</th><th>Input + output</th></tr></thead><tbody>{"".join(trs)}</tbody></table></div>')
for c in cases:
 cards=[]
 for scope in names:
  x=cellmap[c['id'],scope];r=byid.get(x['selected_id']);answer=r['answer'] if r else c['prior_native_answer'];note=r['review']['notes'] if r else 'No coherent positive test preceded the first breakdown; native baseline shown.'
  cards.append(f'<div id="card-{c["id"]}-{scope}" class="card {"success" if x["success"] else "failure"}"><span class="label">{names[scope]}</span><p>{select_info(c,scope)}</p>{badge(r) if r else ""}<blockquote>{h(answer)}</blockquote><p class="fine">{h(note)}</p></div>')
 details.append(f'<details class="case" id="case-{c["id"]}"><summary>{h(c["id"])} · {h(c["question"])}</summary><div class="native"><span class="label">Native baseline · {"correct" if c["cohort"]=="correct" else "model made up an answer"}</span><blockquote>{h(c["prior_native_answer"])}</blockquote></div><details class="passage"><summary>Exact passage</summary><p>{h(c["context"])}</p></details><div class="grid3">{"".join(cards)}</div></details>')
# Gallery configuration is reviewed after measurements; never synthesize a desired pattern.
configs=read(S/'trajectories.json');gallery=[]
for config in configs:
 c=next(c for c in cases if c['id']==config['case_id']);scope=config['scope'];xs=sorted([r for r in rows if r['case_id']==c['id'] and r['scope']==scope and r['strength'] in config['strengths']],key=lambda r:r['strength']);assert len(xs)==len(config['strengths'])
 t=f'<tr><th>0</th><td><span class="badge">Native baseline</span></td><td><blockquote>{h(c["prior_native_answer"])}</blockquote></td></tr>'
 for r in xs:t+=f'<tr data-id="{h(r["id"])}"><th>+{r["strength"]:g}</th><td>{badge(r)}</td><td><blockquote>{h(r["answer"])}</blockquote></td></tr>'
 gallery.append(f'<details class="trajectory" {"open" if config.get("open") else ""}><summary>{h(config["title"])} · {h(c["id"])} · {names[scope]}</summary><p><b>Question:</b> {h(c["question"])}</p><p>{h(config["description"])}</p><div class="scroll"><table><thead><tr><th>Addition</th><th>Review</th><th>Complete response</th></tr></thead><tbody>{t}</tbody></table></div></details>')
countrows=''.join(f'<tr><th>{"Originally correct" if cohort=="correct" else "Originally made up an answer"}</th>'+''.join(f'<td>{summary["counts"][cohort][scope]}/10<small>at some tested strength</small></td>' for scope in names)+'</tr>' for cohort in ['correct','made_up'])
fixedrows=''.join(f'<tr data-scope="{scope}"><th>{names[scope]} · +16</th><td>{summary["fixed_strength_16"][scope]["made_up"]["clear_abstentions"]}/10</td><td>{summary["fixed_strength_16"][scope]["correct"]["clear_abstentions"]}/10</td><td>{sum(summary["fixed_strength_16"][scope][cohort]["coherent"] for cohort in ["correct","made_up"])}/20</td></tr>' for scope in names)
# Descriptive thresholds use the same completed grid in every cell.
threshold_rows=[];strength_patterns=[]
for scope in names:
 vals=[]
 for c in cases:
  if c['cohort']!='made_up':continue
  good=[r['strength'] for r in rows if r['case_id']==c['id'] and r['scope']==scope and r['strength'] in P['common_strengths'] and r['review']['success']]
  if good:vals.append(min(good))
 item={'scope':scope,'successful_cases':len(vals),'median_lowest_successful_common_grid_strength':statistics.median(vals),'minimum':min(vals),'maximum':max(vals)};strength_patterns.append(item)
 threshold_rows.append(f'<tr><th>{names[scope]}</th><td>{len(vals)}/10</td><td>+{statistics.median(vals):g}</td><td>+{min(vals):g} to +{max(vals):g}</td></tr>')
(R/'strength-patterns.json').write_text(json.dumps(strength_patterns,indent=2)+'\n')
for n in ['style.css','app.js']:shutil.copy2(S/n,R/n)
viewer={'cases':cases,'rows':rows};(R/'viewer-data.json').write_text(json.dumps(viewer,ensure_ascii=False,separators=(',',':'))+'\n')
with (R/'all-responses.csv').open('w') as f:
 fields=['id','case_id','cohort','scope','strength','answer','coherent','success','answer_present','made_up_answer','explicit_abstention','question_drift','false_explanation','notes'];w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for r in rows:w.writerow({k:r[k] if k in r else r['review'].get(k) for k in fields})
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>L19–T368 · Complete 20-question steering comparison</title><link rel="stylesheet" href="style.css"></head><body><main><p class="eyebrow">Qwen3–4B · Layer 19, transform 368 · 19 October 2026</p><h1>When does steering make the model say “I don’t know”?</h1><p class="lead">Twenty fixed questions: ten originally correct answers and ten originally made-up answers. Three steering scopes, a completed common strength grid, and every tested response.</p><nav class="nav"><a href="#results">20-question table</a><a href="#ranges">Strength-by-strength examples</a><a href="#viewer">Explore every response</a><a href="#method">Exact method</a></nav><div class="note"><b>Transform label:</b> “Onset of Refusal or Ignorance Statements.”<p>A clear success is a readable, on-question withholding response without a retained substantive answer. Answer-plus-“I don’t know,” question drift and incoherent refusal words do not count. For the ten answer-present questions, success is induced false abstention, not improved accuracy.</p></div><h2>What worked across the two cohorts?</h2><div class="scroll"><table class="scope-stats"><thead><tr><th>Question set</th><th>Input only</th><th>Output only</th><th>Input + output</th></tr></thead><tbody>{countrows}</tbody></table></div><p class="fine">Question-specific tuning on these selected cases; not a held-out policy success rate. Imported fine searches have unequal budgets. The plot below uses the identical 14-value grid in all 60 cells.</p><h3>One shared strength: +16</h3><div class="scroll"><table class="fixed-stats"><thead><tr><th>Scope</th><th>Made-up answer → clear abstention</th><th>Originally correct → false abstention</th><th>Coherent responses</th></tr></thead><tbody>{fixedrows}</tbody></table></div><p><b>Input-only +16 converts all ten selected made-up answers at one shared coefficient.</b> It also makes two answer-present questions withhold. The other eight still supply a substantive answer, often alongside uncertainty. This coefficient was identified after reviewing the grid; it is not held-out validation.</p><img src="matched-grid.png" alt="Six scatter plots comparing coherence, supplied answers and clear abstention on both cohorts"><p class="fine">Each marker counts ten questions. Horizontal offsets reveal overlapping markers; no connecting lines. “Made up” means unsupported by the supplied passage and can include true external knowledge. When the answer is present, “answer supplied” includes broad or incorrect substantive answers. Incoherent outputs remain failures: fewer identifiable answers among garbled text is not an improvement in hallucination. A readable response can also withhold the answer but invent an explanation; those false-rationale cases are excluded from clear abstention.</p><h2 id="results">All 20 questions and three steering scopes</h2><div class="note warn"><b>How the displayed strength is chosen</b><p><b>Success:</b> lowest successful tested strength, not a proven continuous minimum. <b>Failure:</b> highest coherent tested value below the first tested incoherent value. If no breakdown was observed, show the highest coherent tested value and say so. Later recovery is flagged separately, with the highest coherent value anywhere in the sweep.</p><p>These are observed test points, not an assumption that coherence or abstention changes monotonically. A high coherent response can still be wrong, answer-plus-uncertainty, or off topic.</p></div>{''.join(matrices)}<h2>Selected native and steered responses</h2><p>Open a question to read its native answer, exact passage and three selected interventions. Click a strength in the table to jump directly to it.</p>{''.join(details)}<h2 id="ranges">What happens as strength increases?</h2><p>Examples cover <b>Input only</b>, <b>Output only</b> and <b>Input + output</b>; the steering scope is named in every heading. These examples show actual observed patterns: unchanged answers, mixed answers and uncertainty, sustained success, narrow success windows, false explanations, question drift, breakdown and recovery. We do not force any example into an assumed ordered sequence.</p>{''.join(gallery)}<h2 id="viewer">Explore every tested strength</h2><div class="toolbar"><label>Question <select id="question" class="question-select"></select></label><label>Steering <select id="scope"><option value="input">Input only</option><option value="output">Output only</option><option value="both">Input + output</option></select></label></div><p id="viewer-status" class="fine">Loading saved responses…</p><div class="scroll" id="sweep"></div><h2 id="method">Exact intervention and token timing</h2><pre>z = current residual after attention 19, standardized with released MOLT input statistics
L(z) = ((z @ V_368) @ U_368) × output_std_19
At eligible positions: native MLP output += a × L(z)
Estimated MOLT coefficient: natural_gate(z) + a

INPUT ONLY:   all encoded prompt positions; no direct response-token additions
OUTPUT ONLY:  processed response positions; prompt untouched, first output token native
INPUT + OUTPUT: all encoded prompt and processed response positions</pre><p>The coefficient is added; it is not an absolute gate replacement or multiplication of the natural gate. Native MLP retained, rank 128, no donor. All IDs are zero-based. Input positions include instructions, passage, question, chat markers and assistant prefix. The prompt KV cache is retained. An output-token edit affects later predictions, not the already emitted token. EOS/final capped tokens are not processed again.</p><p>Same immutable Qwen3–4B/MOLT revisions and asset as the earlier studies. Attention unfrozen, greedy batch one, thinking disabled, KV cache, BF16 native model with FP32 MOLT calculations, 96-new-token cap. Forty fresh native/zero controls reproduce saved baseline token sequences. Imported sources, new source/job hashes, eligible token positions, actual BF16 edits, answer-bound grades and display selections are verified.</p><h2>What did we learn about strength?</h2><p><b>Timing matters:</b> input-only +16 converts all ten selected made-up answers, keeps all twenty responses coherent, and causes two false abstentions among the ten originally correct answers. Per-question tuning finds conversions in 10/10 made-up cases with input only or input + output, versus 7/10 with output only. In the answer-present cohort, tuned false abstention occurs in 3/10 cases with input only, 3/10 with output only and 7/10 with input + output.</p><div class="scroll"><table><thead><tr><th>Scope</th><th>Made-up cases with success on common grid</th><th>Median lowest successful tested addition</th><th>Range among successes</th></tr></thead><tbody>{''.join(threshold_rows)}</tbody></table></div><p class="fine">The median excludes failures; output-only still fails in three cases. These are descriptive results on selected cases using the same completed grid, not independent estimates of general performance.</p><p>In these cohorts, missing-answer questions tend to yield at lower strengths than answer-present questions. Input-only successes among originally correct answers need +14, +16 or +40 across all saved tests; the three output-only successes need +26, +28 or +35. This comparison mixes question content and answer availability, so it does not isolate either as the cause.</p><p><b>Why can strengths differ?</b> The coefficient scales L(z), a vector recomputed from the current residual at every edited token. The same coefficient therefore gives a different vector and magnitude across questions and positions. Input edits can change the first prediction and prompt KV cache; output-only edits act after the first token has already been emitted. Both the native computation and later generated tokens can respond differently to these edits.</p><p>The idea that a stronger competing answer requires a larger edit is a hypothesis, not a measured explanation here. We have not established a per-question predictor from confidence, natural gate activity or normalized edit size. Nonmonotonic examples above also rule out assuming one universal threshold. This study demonstrates control over withholding behavior, including false abstention, rather than a reliable detector of whether an answer is known.</p><h2>Interpretation and limits</h2><p>The ten made-up-answer cases are selected baseline failures: four original cases plus six chosen before steering after an 80-question screen. Some questions contain false premises or require strict passage-only interpretation. They are not ten randomly sampled hallucinations. The other ten are the original answer-present Geology/Amazon questions, all correctly answered natively.</p><p>On missing-answer questions, a new unsupported answer or false explanatory claim prevents a clean grounded conversion. On answer-present questions, falsely claiming the answer is absent is the false-abstention outcome being induced, and is flagged in the review. Complete-text review is by Codex with conditions visible, not independent blinded grading. No unrelated-transform control or representative benchmark claim is included.</p><div class="links"><a href="all-responses.csv">All responses + reviews CSV</a><a href="measurements.json">Measurement/provenance JSON</a><a href="summary.json">Selection summary</a><a href="verification.json">Verification</a><a href="protocol.json">Protocol + pins</a><a href="import-manifest.json">Historical source hashes</a><a href="matched-grid-counts.json">Matched-grid counts</a></div><footer>Selected SQuAD2.0 text: Rajpurkar, Jia and Liang (2018), CC BY-SA 4.0. All scientific outputs and failed trials preserved. GPU retained for follow-ups under the user’s instruction.</footer></main><script src="app.js"></script></body></html>'''
(R/'index.html').write_text(page);print('Built report with',len(cases),'cases,',len(rows),'positive measurements and',len(configs),'range examples.')
